def decode(encoded: str, original: str, message: str) -> str:
    # Check length consistency
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"  # Contradiction
        else:
            mapping[e] = o
    # Ensure all 26 uppercase letters are represented in the mapping
    if len(mapping) < 26:
        return "Failed"
    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])
    return "".join(decoded_chars)

